import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { dirname, join, relative, resolve, sep } from "node:path";
import { glob } from "glob";
const TEST_RESULTS_REGISTRY_FILENAME = "test-results.json";
const QUALITY_GATE_RESULTS_FILENAME = "quality-gate.json";
const ARTIFACTS_MANIFEST_FILENAME = "artifacts.json";
const SUMMARY_FILENAME = "summary.json";
const TEST_STATUSES = ["failed", "broken", "passed", "skipped", "unknown"];
const emptyStatusStats = () => ({
    failed: 0,
    broken: 0,
    passed: 0,
    skipped: 0,
    unknown: 0,
    total: 0,
});
const emptyFlagStats = () => ({
    new: 0,
    flaky: 0,
    retry: 0,
});
const emptyResolutionStats = () => ({
    issues: 0,
    muted: 0,
    accepted: 0,
});
const isRecord = (value) => typeof value === "object" && value !== null && !Array.isArray(value);
const isTestStatus = (value) => typeof value === "string" && TEST_STATUSES.includes(value);
const getFiniteNumber = (value, fallback = 0) => typeof value === "number" && Number.isFinite(value) ? value : fallback;
const normalizePath = (filePath) => filePath.split(sep).join("/");
const readOptionalJson = async (filePath, onError) => {
    if (!existsSync(filePath)) {
        return undefined;
    }
    try {
        return JSON.parse(await readFile(filePath, "utf8"));
    }
    catch (err) {
        onError?.(`Failed to read Allure report context file ${filePath}: ${String(err)}`);
        return undefined;
    }
};
const getReportName = (summary) => {
    if (typeof summary.name === "string" && summary.name.trim()) {
        return summary.name;
    }
    return "Allure Report";
};
const hasPluginSummarySignal = (value) => typeof value.name === "string" ||
    typeof value.plugin === "string" ||
    typeof value.href === "string" ||
    typeof value.remoteHref === "string" ||
    isRecord(value.stats);
const isPluginSummary = (value) => {
    if (!isRecord(value) || !hasPluginSummarySignal(value)) {
        return false;
    }
    return true;
};
const normalizePluginSummaryStats = (summary) => {
    const rawStats = isRecord(summary.stats) ? summary.stats : {};
    const stats = {
        ...rawStats,
        failed: getFiniteNumber(rawStats.failed),
        broken: getFiniteNumber(rawStats.broken),
        passed: getFiniteNumber(rawStats.passed),
        skipped: getFiniteNumber(rawStats.skipped),
        unknown: getFiniteNumber(rawStats.unknown),
    };
    stats.total = getFiniteNumber(rawStats.total, TEST_STATUSES.reduce((acc, status) => acc + getFiniteNumber(stats[status]), 0));
    return stats;
};
const normalizePluginSummary = (summary) => ({
    ...summary,
    name: getReportName(summary),
    stats: normalizePluginSummaryStats(summary),
    status: isTestStatus(summary.status) ? summary.status : "passed",
    duration: getFiniteNumber(summary.duration),
});
const getReportPath = (reportDir, summaryFile) => normalizePath(relative(resolve(reportDir), dirname(resolve(summaryFile))));
const readPluginSummary = async (reportDir, filePath, onError) => {
    const value = await readOptionalJson(filePath, onError);
    if (value === undefined) {
        return undefined;
    }
    if (!isPluginSummary(value)) {
        onError?.(`Ignoring unsupported Allure plugin summary file ${filePath}`);
        return undefined;
    }
    return {
        ...normalizePluginSummary(value),
        summaryFile: filePath,
        reportPath: getReportPath(reportDir, filePath),
    };
};
const findSummaryFiles = async (reportDir) => (await glob(`**/${SUMMARY_FILENAME}`, {
    absolute: true,
    cwd: reportDir,
    ignore: [`**/widgets/${SUMMARY_FILENAME}`],
    nodir: true,
})).toSorted((left, right) => left.localeCompare(right));
const normalizeTestResultRegistry = (value, onError) => {
    if (!isRecord(value) || !isRecord(value.byId)) {
        if (value !== undefined) {
            onError?.("Ignoring unsupported Allure test result registry shape");
        }
        return undefined;
    }
    return {
        byId: value.byId,
    };
};
const normalizeArtifacts = (value, onError) => {
    if (value === undefined) {
        return [];
    }
    if (!Array.isArray(value)) {
        onError?.("Ignoring unsupported Allure artifacts manifest shape");
        return [];
    }
    const byPath = new Map();
    value.forEach((artifact) => {
        if (!isRecord(artifact) || typeof artifact.name !== "string" || typeof artifact.path !== "string") {
            return;
        }
        if (!byPath.has(artifact.path)) {
            byPath.set(artifact.path, {
                name: artifact.name,
                path: artifact.path,
            });
        }
    });
    return [...byPath.values()].toSorted((left, right) => left.path.localeCompare(right.path) || left.name.localeCompare(right.name));
};
const isQualityGateResult = (value) => {
    if (!isRecord(value)) {
        return false;
    }
    return typeof value.success === "boolean" && typeof value.rule === "string" && typeof value.message === "string";
};
const normalizeQualityGate = (value, onError) => {
    if (Array.isArray(value)) {
        return value.filter(isQualityGateResult);
    }
    if (!isRecord(value)) {
        if (value !== undefined) {
            onError?.("Ignoring unsupported Allure quality gate results shape");
        }
        return undefined;
    }
    const entries = Object.entries(value).flatMap(([environment, results]) => Array.isArray(results) ? [[environment, results.filter(isQualityGateResult)]] : []);
    if (!entries.length) {
        if (Object.keys(value).length > 0) {
            onError?.("Ignoring unsupported Allure quality gate results shape");
        }
        return undefined;
    }
    return Object.fromEntries(entries);
};
const addStatus = (stats, status) => {
    stats[status] += 1;
    stats.total += 1;
};
const getSummaryIdSet = (summaries, key) => new Set(summaries.flatMap((summary) => summary[key] ?? []));
const applyMaxSummaryStats = (stats, summaries) => {
    summaries.forEach((summary) => {
        TEST_STATUSES.forEach((status) => {
            stats[status] = Math.max(stats[status], summary.stats[status] ?? 0);
        });
        stats.total = Math.max(stats.total, summary.stats.total);
    });
};
const createTotals = (registry, summaries) => {
    const totals = {
        stats: emptyStatusStats(),
        flags: emptyFlagStats(),
        resolutions: emptyResolutionStats(),
        duration: 0,
    };
    if (!registry) {
        applyMaxSummaryStats(totals.stats, summaries);
        totals.duration = summaries.reduce((max, summary) => Math.max(max, summary.duration), 0);
        return totals;
    }
    Object.values(registry.byId).forEach((testResult) => {
        if (!isRecord(testResult) || !isTestStatus(testResult.status)) {
            return;
        }
        addStatus(totals.stats, testResult.status);
        if (typeof testResult.duration === "number") {
            totals.duration += testResult.duration;
        }
    });
    return totals;
};
const addFlags = (flags, testResultId, newTestIds, flakyTestIds, retryTestIds) => {
    if (newTestIds.has(testResultId)) {
        flags.new += 1;
    }
    if (flakyTestIds.has(testResultId)) {
        flags.flaky += 1;
    }
    if (retryTestIds.has(testResultId)) {
        flags.retry += 1;
    }
};
const createEnvironmentContext = (registry, summaries) => {
    if (!registry) {
        return [];
    }
    const newTestIds = getSummaryIdSet(summaries, "newTests");
    const flakyTestIds = getSummaryIdSet(summaries, "flakyTests");
    const retryTestIds = getSummaryIdSet(summaries, "retryTests");
    const environmentsByName = new Map();
    Object.entries(registry.byId).forEach(([testResultId, testResult]) => {
        if (!isRecord(testResult) || !isTestStatus(testResult.status) || typeof testResult.environment !== "string") {
            return;
        }
        const environment = testResult.environment.trim();
        if (!environment || environment === "default") {
            return;
        }
        const context = environmentsByName.get(environment) ?? {
            name: environment,
            stats: emptyStatusStats(),
            flags: emptyFlagStats(),
            duration: 0,
        };
        addStatus(context.stats, testResult.status);
        addFlags(context.flags, testResultId, newTestIds, flakyTestIds, retryTestIds);
        if (typeof testResult.duration === "number") {
            context.duration += testResult.duration;
        }
        environmentsByName.set(environment, context);
    });
    return [...environmentsByName.values()].toSorted((left, right) => left.name.localeCompare(right.name));
};
const createReport = (summary) => normalizePluginSummary(summary);
const sortReports = (reports) => reports
    .map((report) => normalizePluginSummary(report))
    .toSorted((left, right) => left.name.localeCompare(right.name));
const getResolutionStats = (summaries) => {
    const stats = emptyResolutionStats();
    summaries.forEach((summary) => {
        stats.issues = Math.max(stats.issues, summary.stats.resolutions?.issues ?? 0);
        stats.muted = Math.max(stats.muted, summary.stats.resolutions?.muted ?? 0);
        stats.accepted = Math.max(stats.accepted, summary.stats.resolutions?.accepted ?? 0);
    });
    return stats;
};
const applySummaryFlags = (totals, summaries) => {
    totals.flags.new = getSummaryIdSet(summaries, "newTests").size;
    totals.flags.flaky = getSummaryIdSet(summaries, "flakyTests").size;
    totals.flags.retry = getSummaryIdSet(summaries, "retryTests").size;
    totals.resolutions = getResolutionStats(summaries);
};
export const readReportContextFiles = async (reportDir, options = {}) => {
    const { onError } = options;
    const summaryFiles = await findSummaryFiles(reportDir);
    const reports = (await Promise.all(summaryFiles.map((summaryFile) => readPluginSummary(reportDir, summaryFile, onError)))).filter((summary) => summary !== undefined);
    const registry = normalizeTestResultRegistry(await readOptionalJson(join(reportDir, TEST_RESULTS_REGISTRY_FILENAME), onError), onError);
    const artifacts = normalizeArtifacts(await readOptionalJson(join(reportDir, ARTIFACTS_MANIFEST_FILENAME), onError), onError);
    const qualityGate = normalizeQualityGate(await readOptionalJson(join(reportDir, QUALITY_GATE_RESULTS_FILENAME), onError), onError);
    return {
        reports,
        testResults: registry,
        artifacts,
        qualityGate,
    };
};
export const createReportContextFromData = (data) => {
    const reports = sortReports(data.reports ?? data.summaries?.map(createReport) ?? []);
    const artifacts = [...(data.artifacts ?? [])].toSorted((left, right) => left.path.localeCompare(right.path) || left.name.localeCompare(right.name));
    const totals = createTotals(data.testResults, reports);
    applySummaryFlags(totals, reports);
    return {
        reports,
        testResults: data.testResults,
        totals,
        environments: createEnvironmentContext(data.testResults, reports),
        artifacts,
        qualityGate: data.qualityGate,
    };
};
export const createReportContext = async (reportDir, options = {}) => createReportContextFromData(await readReportContextFiles(reportDir, options));
